/** 古籍阅读术语词典：注释文 / 白话文视图的数据源。
 * plain = 白话短义（用于白话对照替换与悬浮提示）；note = 注释（来历/要点）。
 * 收词原则：只收文中真实出现且可下确定定义的术数术语，宁缺毋滥（严禁编造义理）。
 */
export interface GlossaryEntry { plain: string; note?: string }

