  六害: { plain: '地支六害：子未、丑午、寅巳、卯辰、申亥、酉戌，主暗损、关系不和、穿小鞋、暗地里搞破坏', note: '六害=暗地里互相伤害：穿小鞋、暗算、背地里搞破坏。不如六冲明显，但比六冲阴。六合变六害=本来好的朋友/夫妻，最后暗地闹翻。' },
